<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { createSelection, getGameProfile, getProduct, newRequestKey, profileRequest, updateSelection } from '../api'

const props=defineProps<{product:string;listing?:string;date:string;tab?:string;version?:string;market?:string}>()
const emit=defineEmits<{back:[];navigate:[scope:{listing:string;date:string;tab:string}]}>()
const dossier=ref<any>(null),busy=ref(false),error=ref(''),scope=ref(props.listing||''),day=ref(props.date),tab=ref(props.tab||'overview')
const definitions=ref<any>({fields:[]}),search=ref(''),statusFilter=ref(''),evidenceTab=ref('fields')
const fieldOpen=ref(false),fieldHistory=ref<any[]>([]),selectedField=ref<any>(null),evidence=ref<any>(null),evidenceError=ref('')
const taskOpen=ref(false),task=reactive<any>({}),materialOpen=ref(false),reviewOpen=ref(false),selectedSubmission=ref<any>(null)
const selectionOpen=ref(false),selection=reactive<any>({}),selectable=ref<any>({rankings:[]}),actionBusy=ref(false)
const tabs=[['overview','档案概览'],['gameplay','玩法与体验'],['market','市场表现'],['voices','玩家声音'],['monetization','广告与变现'],['competition','竞品与制作'],['evidence','证据与补全'],['records','选用记录']]
const labels:Record<string,string>={available:'有资料',missing:'未采集',not_authorized:'权限受限',not_supported:'来源不支持',not_yet_known:'当时未形成',stale:'需重新核查',conflict:'证据冲突',not_applicable:'不适用',OBSERVED:'已观察',MISSING_SNAPSHOT:'无快照',out_of_monitored_range:'监测范围外',PARTIAL_COVERAGE:'部分覆盖',pending:'待处理',in_progress:'处理中',pending_review:'待复核',unavailable:'暂不可得',completed:'已完成',approved:'已通过',rejected:'已拒绝',needs_material:'需补材料'}
const kinds:Record<string,string>={observed:'来源事实',manual:'人工核查',estimated:'供应商/人工估计',derived:'计算指标',inference:'AI分析草案'}
const platforms:Record<string,string>={WECHAT:'微信',DOUYIN:'抖音',IOS:'iOS',GOOGLE_PLAY:'Google Play'}
const material=reactive<any>({fieldKey:'summary',kind:'manual',status:'available',valueText:'',submitter:'',observedAt:'',sourceName:'',originFamily:'',sourceUrl:'',locator:'',excerpt:'',rights:'public_excerpt',appVersion:'',validUntil:'',reason:'',noIapBasis:'',adBasis:'',scopeConfirmed:false,mediaKind:'',modelMetadata:{model:'',promptVersion:'',schemaVersion:'',inputHash:''}})
const review=reactive<any>({reviewer:'',decision:'approved',reason:'',supersedesId:''})
const fields=computed<any[]>(()=>Object.values(dossier.value?.fields||{}))
const shownFields=computed(()=>fields.value.filter(f=>(tab.value==='evidence'||f.tab===tab.value)&&(search.value===''||`${f.key} ${f.label}`.toLowerCase().includes(search.value.toLowerCase()))&&(!statusFilter.value||f.status===statusFilter.value)))
const domains=computed(()=>dossier.value?.domains||[])
const collab=computed(()=>dossier.value?.collaboration||{tasks:[],submissions:[],selections:[]})
const cov=computed(()=>dossier.value?.coverage||{})
const chartIds=computed(()=>[...new Set((dossier.value?.series||[]).map((p:any)=>p.chartId).filter(Boolean))])
const selectedChart=ref<any>(null)
const points=computed(()=>(dossier.value?.series||[]).filter((p:any)=>!selectedChart.value||String(p.chartId)===String(selectedChart.value)))
const valueText=(v:any):string=>v===null||v===undefined?'—':typeof v==='object'?JSON.stringify(v,null,2):String(v)
const safeUrl=(v:any)=>typeof v==='string'&&/^https?:\/\//.test(v)?v:null
const dateTime=(v:any)=>v?`${String(v).replace('T',' ')} UTC`:'—'
function navigate(){emit('navigate',{listing:scope.value,date:day.value,tab:tab.value})}
let loadSeq=0
async function load(){const seq=++loadSeq;busy.value=true;error.value='';try{const p=await getGameProfile(props.product,scope.value,day.value,scope.value?undefined:props.version,scope.value?undefined:props.market);if(seq!==loadSeq)return;dossier.value=p;scope.value=String(p.listing.id);selectedChart.value=chartIds.value[0]||null;navigate()}catch(e:any){error.value=e.message}finally{if(seq===loadSeq)busy.value=false}}
watch(()=>props.product,()=>{scope.value=props.listing||'';load()})
watch(()=>[props.listing,props.date,props.tab],()=>{if(props.listing===scope.value&&props.date===day.value&&props.tab===tab.value)return;scope.value=props.listing||'';day.value=props.date;tab.value=props.tab||'overview';load()})
onMounted(async()=>{try{definitions.value=await profileRequest('/api/v1/profile/definitions')}catch(e:any){error.value=e.message}await load()})
async function act(fn:()=>Promise<void>){if(actionBusy.value)return;actionBusy.value=true;try{await fn()}catch(e:any){ElMessage.error(e.message)}finally{actionBusy.value=false}}
async function plan(){await act(async()=>{const r=await profileRequest('/api/v1/profile/tasks/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({listingId:scope.value,asOf:day.value})});ElMessage.success(`新增${r.created}个补全任务；进行中任务已去重`);await load();tab.value='evidence';evidenceTab.value='tasks';navigate()})}
async function showField(f:any){selectedField.value=f;evidence.value=null;evidenceError.value='';fieldOpen.value=true;try{fieldHistory.value=await profileRequest(`/api/v1/profile/listings/${scope.value}/fields/${f.key}/history?asOf=${day.value}`)}catch(e:any){fieldHistory.value=[];evidenceError.value=e.message}}
async function showEvidence(id:any){try{evidence.value=await profileRequest(`/api/v1/profile/evidence/${id}?asOf=${day.value}`);evidenceError.value=''}catch(e:any){evidence.value=null;evidenceError.value=`无法回放：${e.message}`}}
function editTask(row:any){Object.assign(task,row,{owner:row.owner_name,retryCondition:row.retry_condition});taskOpen.value=true}
async function saveTask(){await act(async()=>{await profileRequest(`/api/v1/profile/tasks/${task.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({owner:task.owner,status:task.status,note:task.note||'更新进度',retryCondition:task.retryCondition,expectedRevision:task.revision})});taskOpen.value=false;await load()})}
function addMaterial(fieldKey='summary'){Object.assign(material,{fieldKey,valueText:'',submitter:'',observedAt:day.value,sourceName:'',originFamily:'',sourceUrl:'',locator:'',excerpt:'',appVersion:dossier.value?.currentRelease?.app_version||'',reason:'',validUntil:'',scopeConfirmed:false,mediaKind:''});materialOpen.value=true}
async function submitMaterial(){await act(async()=>{const definition=definitions.value.fields.find((f:any)=>f.key===material.fieldKey);let value:any=material.valueText;if(['list','number','range','object'].includes(definition?.type))value=JSON.parse(value);if(material.status!=='available')value=null;const b={...material,listingId:scope.value,value,validUntil:material.validUntil||null,sourceUrl:material.sourceUrl||null};delete b.valueText;await profileRequest('/api/v1/profile/submissions',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':newRequestKey()},body:JSON.stringify(b)});ElMessage.success('已提交待复核；当前档案事实和资格不变');materialOpen.value=false;await load()})}
function startReview(s:any){selectedSubmission.value=s;Object.assign(review,{reviewer:'',decision:'approved',reason:'',supersedesId:''});reviewOpen.value=true}
async function saveReview(){await act(async()=>{await profileRequest(`/api/v1/profile/submissions/${selectedSubmission.value.id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...review,supersedesId:review.supersedesId?Number(review.supersedesId):null,expectedRevision:selectedSubmission.value.revision})});reviewOpen.value=false;ElMessage.success('已保存复核审计；历史档案按当时已知资料回放');await load()})}
async function exportProfile(){await act(async()=>{const result=await profileRequest(`/api/v1/products/${props.product}/profile-export?listingId=${scope.value}&asOf=${day.value}`);const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`游戏档案-${props.product}-${scope.value}-${day.value}.json`;a.click();URL.revokeObjectURL(url)})}
async function editSelection(row?:any){try{selectable.value=await getProduct(props.product,day.value);Object.assign(selection,{id:row?.id,owner:row?.owner_name||'',referenceVersionId:row?.reference_version_id||dossier.value.listing.platform_version_id,status:row?.status||'SELECTED',selectedOn:row?.selected_on||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date()),startedOn:row?.started_on||'',finishedOn:row?.finished_on||'',note:row?.note||'',version:row?.version||0});selectionOpen.value=true}catch(e:any){ElMessage.error(e.message)}}
async function saveSelection(){await act(async()=>{const b={...selection,startedOn:selection.startedOn||null,finishedOn:selection.finishedOn||null};if(selection.id)await updateSelection(String(selection.id),b);else await createSelection(props.product,b);selectionOpen.value=false;await load()})}
function domainTab(d:any){tab.value=d.tab||'overview';search.value='';statusFilter.value='';navigate()}
</script>

<template>
<section class="profile-page" v-loading="busy">
  <div class="profile-back"><el-button link @click="emit('back')">← 返回产品库</el-button><span>产品 / 平台市场 / 应用版本 / 知识日</span></div>
  <el-alert v-if="error" type="error" :title="error" :closable="false" show-icon/>
  <template v-if="dossier">
    <div class="profile-heading"><div><h1>{{valueText(dossier.fields.name.value)==='—'?`游戏档案 #${product}`:valueText(dossier.fields.name.value)}}</h1><p>{{dossier.fields.summary.status==='available'?valueText(dossier.fields.summary.value):'玩法待核验，先补实机与核心循环材料'}}</p><div class="profile-badges"><el-tag :type="dossier.isSynthetic?'warning':'info'">{{dossier.isSynthetic?'模拟档案':'来源资料 · 独立核查'}}</el-tag><el-tag :type="dossier.qualification.eligible?'success':'warning'">{{dossier.qualification.label}}</el-tag><span>应用版本 {{dossier.currentRelease?.app_version||'未核验'}}</span></div></div><div class="profile-actions"><el-button @click="exportProfile" :loading="actionBusy">导出档案</el-button><el-button @click="plan" :loading="actionBusy">生成补全清单</el-button><el-button type="primary" @click="editSelection()">新增选用</el-button></div></div>
    <div class="profile-scope"><label>目标平台市场<el-select v-model="scope" @change="load" aria-label="目标平台市场"><el-option v-for="l in dossier.listings" :key="l.id" :value="String(l.id)" :label="`${platforms[l.platform]||l.platform} · ${l.market} · ${l.language}`"/></el-select></label><label>知识截止日<el-date-picker v-model="day" type="date" value-format="YYYY-MM-DD" :clearable="false" @change="load" aria-label="档案知识截止日"/></label><span>仅显示当时已观察且已获知的资料；协作记录展示当前进度。</span></div>
    <div class="profile-stats"><div><span>当日独立榜单</span><b>{{points.filter((p:any)=>p.date===day&&p.rank!=null).map((p:any)=>`#${p.rank}`).join(' / ')||'无快照 / 未在榜内'}}</b><small>不跨榜计算综合名次</small></div><div><span>当前可读资料</span><b>{{cov.readable}} / {{cov.applicable}}</b><small>其中 AI 草案 {{cov.aiDrafts}} 项，不适用 {{cov.notApplicable}} 项</small></div><div><span>本次评价样本</span><b>{{dossier.fields.sample.status==='available'?valueText(dossier.fields.sample.value):'未采样'}}</b><small>评分数、评论数与分析分母分别记录</small></div><div><span>待补资料</span><b>{{cov.missing}} 项</b><small>先补身份、IAA、实机与制作依赖</small></div></div>
    <div class="profile-tabs" role="tablist"><button v-for="t in tabs" :key="t[0]" role="tab" :aria-selected="tab===t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]!;search='';statusFilter='';navigate()">{{t[1]}}</button></div>
    <template v-if="tab==='overview'"><div class="profile-panel"><h2>12域资料地图</h2><p class="muted">{{cov.notice}}</p><div class="profile-domain-grid"><button v-for="d in domains" :key="d.id" @click="domainTab(d)"><b>{{d.name}}</b><span>{{fields.filter(f=>f.domain===d.id&&f.status==='available').length}} / {{fields.filter(f=>f.domain===d.id&&f.status!=='not_applicable').length}} 项</span></button></div></div><div class="profile-panel"><h2>实机与素材</h2><p class="muted">实机截图、实机视频、广告视频分开留存；外部链接不代表已获取媒体文件。</p><div class="profile-media"><div v-for="kind in [['gameplay_screenshot','实机截图'],['gameplay_video','实机视频'],['ad_video','广告素材'],['diagram','结构示意']]" :key="kind[0]"><b>{{kind[1]}}</b><template v-if="dossier.media.some((m:any)=>m.media_kind===kind[0])"><p v-for="m in dossier.media.filter((m:any)=>m.media_kind===kind[0])" :key="m.id"><a v-if="safeUrl(m.source_url)&&m.rights!=='not_authorized'" :href="safeUrl(m.source_url)!" target="_blank" rel="noopener noreferrer">打开来源 ↗</a><span v-else>{{labels[m.status]||'无法回放'}}</span><small>{{dateTime(m.observed_at)}}</small></p></template><p v-else>未采集 · 待补材料</p></div></div></div></template>
    <div v-if="tab==='market'" class="profile-panel"><div class="profile-section-head"><h2>14日同榜轨迹</h2><el-select v-if="chartIds.length" v-model="selectedChart" aria-label="档案榜单"><el-option v-for="c in chartIds" :key="String(c)" :value="c" :label="dossier.series.find((p:any)=>p.chartId===c)?.chartName"/></el-select></div><p class="muted">历史最佳与有效采样日限定本窗口及所选单榜；空白不补前值、不记作0或第101名。</p><div class="profile-rank-series"><div v-for="(p,i) in points" :key="i" :title="`${p.date} ${labels[p.state]||p.state}`"><strong>{{p.rank===null?'—':`#${p.rank}`}}</strong><span>{{String(p.date).slice(5)}}</span><small>{{labels[p.state]||p.state}}</small></div></div></div>
    <div v-if="tab==='voices'" class="profile-panel"><h2>玩家与舆情口径</h2><p>只展示当前平台、市场与语言的材料。评分不换算好评率；评价样本未知时不从评分数推算情感分母。转载和商业内容不能当作独立自然热度。</p></div>
    <div v-if="tab==='monetization'" class="profile-panel"><h2>{{dossier.qualification.label}}</h2><p>纯IAA需目标应用版本的广告依据、排除内购核查、适用范围与可追溯复核。AI草案、含广告标签和未发现购买入口都不足以独立证明资格。</p></div>
    <template v-if="tab==='evidence'"><div class="profile-subtabs"><el-radio-group v-model="evidenceTab"><el-radio-button value="fields">字段证据</el-radio-button><el-radio-button value="tasks">补全任务 {{collab.tasks.length}}</el-radio-button><el-radio-button value="submissions">待复核材料 {{collab.submissions.length}}</el-radio-button></el-radio-group><el-button @click="addMaterial()">补充材料</el-button></div>
      <div v-if="evidenceTab==='tasks'" class="profile-panel"><p class="muted">任务与负责人是当前协作记录，不随历史市场日期回退；完成任务不会自动修改资料或资格。</p><el-table :data="collab.tasks"><el-table-column label="信息域" min-width="140"><template #default="{row}">{{domains.find((d:any)=>d.id===row.domain_key)?.name||row.domain_key}}</template></el-table-column><el-table-column prop="priority" label="优先级" width="80"/><el-table-column prop="owner_name" label="负责人" min-width="120"/><el-table-column label="状态" width="110"><template #default="{row}">{{labels[row.status]}}</template></el-table-column><el-table-column prop="note" label="进度 / 结果" min-width="180"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="editTask(row)">更新</el-button></template></el-table-column></el-table></div>
      <div v-if="evidenceTab==='submissions'" class="profile-panel"><el-table :data="collab.submissions"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="field_key" label="字段" min-width="120"/><el-table-column label="材料" min-width="240"><template #default="{row}"><p>{{row.material.sourceName}} · {{kinds[row.material.kind]||row.material.rights}}</p><p>{{row.material.excerpt||'权限受限，不能回放原文'}}</p><small>{{row.material.submitter}} · {{row.material.observedAt}}</small></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{labels[row.status]}}</template></el-table-column><el-table-column label="复核" width="95"><template #default="{row}"><el-button v-if="['pending_review','needs_material'].includes(row.status)" link type="primary" @click="startReview(row)">复核</el-button><span v-else>{{row.reviews?.length}}条审计</span></template></el-table-column></el-table></div>
    </template>
    <div v-if="tab!=='records'&&(tab!=='evidence'||evidenceTab==='fields')" class="profile-panel"><div class="profile-section-head"><h2>{{tab==='evidence'?'字段依据与历史':'范围内资料'}}</h2><div class="profile-field-filters"><el-input v-model="search" placeholder="搜索字段名称或键" clearable/><el-select v-model="statusFilter" placeholder="全部字段状态" clearable><el-option v-for="(label,state) in labels" :key="state" :value="state" :label="label"/></el-select></div></div><div class="profile-fields"><div v-for="f in shownFields" :key="f.key" class="profile-field"><div><b>{{f.label}}</b><small>{{f.key}}</small><el-tag size="small" :type="['conflict','stale'].includes(f.status)?'warning':'info'">{{labels[f.status]||f.status}}</el-tag></div><div><p class="profile-value">{{valueText(f.value)}}</p><span class="muted">{{kinds[f.kind]||'暂无依据'}}<template v-if="f.availableAt"> · {{dateTime(f.availableAt)}}</template><template v-if="f.appVersion"> · v{{f.appVersion}}</template></span><p v-if="f.reason" class="muted">{{f.reason}}</p></div><div class="profile-field-actions"><el-button link type="primary" @click="showField(f)">依据与历史</el-button><el-button link @click="addMaterial(f.key)">补材料</el-button></div></div></div></div>
    <div v-if="tab==='records'" class="profile-panel"><div class="profile-section-head"><h2>多人独立选用 · 当前状态</h2><el-button type="primary" @click="editSelection()">添加记录</el-button></div><p class="muted">历史市场日期不改变当前制作进度；同一产品允许多位负责人分别记录。制作完成不等于测试通过。</p><el-table :data="collab.selections"><el-table-column prop="owner_name" label="负责人" min-width="110"/><el-table-column prop="reference_version_id" label="参考平台实体" min-width="120"/><el-table-column prop="status" label="状态" width="120"/><el-table-column prop="selected_on" label="选用日期" width="120"/><el-table-column prop="note" label="说明" min-width="180"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="editSelection(row)">编辑</el-button></template></el-table-column></el-table></div>
  </template>
  <el-drawer v-model="fieldOpen" :title="`${selectedField?.label||''} · 字段依据`" size="min(720px,96vw)"><p>状态 {{labels[selectedField?.status]}} · 目标版本 {{dossier?.currentRelease?.app_version||'未核验'}} · 截至 {{day}}</p><p v-if="selectedField?.source_url"><a :href="safeUrl(selectedField.source_url)!" target="_blank" rel="noopener noreferrer">来源页面 ↗</a> · 材料哈希 {{selectedField.raw_sha256}}</p><el-empty v-if="!fieldHistory.length" description="无人工字段历史；已有来源投影仅代表冻结快照中的资料"/><div v-for="h in fieldHistory" :key="h.id" class="profile-history"><b>{{valueText(h.value)}}</b><p>{{labels[h.status]}} · {{kinds[h.kind]}} · {{h.appVersion||'不绑定版本'}}</p><p>观察 {{dateTime(h.observedAt)}}<br>可用 {{dateTime(h.availableAt)}}<br>到期 {{dateTime(h.validUntil)}}</p><p>{{h.reason}} · 复核人 {{h.reviewer||'AI草案'}}</p><el-button v-if="h.evidenceId" link type="primary" @click="showEvidence(h.evidenceId)">查看证据 #{{h.evidenceId}}</el-button></div><el-alert v-if="evidenceError" :title="evidenceError" type="warning"/><div v-if="evidence" class="profile-history"><h3>{{evidence.source_name}}</h3><p>{{evidence.excerpt}}</p><p>定位 {{evidence.locator}} · 权限 {{evidence.rights}}</p><p class="profile-hash">SHA256 {{evidence.content_sha256}}</p><a v-if="safeUrl(evidence.source_url)" :href="safeUrl(evidence.source_url)!" target="_blank" rel="noopener noreferrer">打开原始来源 ↗</a></div></el-drawer>
  <el-dialog v-model="taskOpen" title="更新补全任务" width="min(600px,94vw)"><el-form label-position="top"><el-form-item label="负责人"><el-input v-model="task.owner"/></el-form-item><el-form-item label="状态"><el-select v-model="task.status"><el-option v-for="s in ['pending','in_progress','pending_review','unavailable','completed']" :key="s" :value="s" :label="labels[s]"/></el-select></el-form-item><el-form-item label="进度 / 结果 / 不可得原因"><el-input v-model="task.note" type="textarea"/></el-form-item><el-form-item label="后续复查条件（暂不可得时必填）"><el-input v-model="task.retryCondition"/></el-form-item></el-form><template #footer><el-button @click="taskOpen=false">取消</el-button><el-button type="primary" :loading="actionBusy" @click="saveTask">保存进度</el-button></template></el-dialog>
  <el-dialog v-model="materialOpen" title="提交材料 · 待复核" width="min(800px,94vw)"><el-alert title="提交不会改变字段事实或IAA资格；来源文本中的指令不构成系统操作授权。" type="info" :closable="false"/><el-form label-position="top" class="profile-form"><el-form-item label="目标字段"><el-select v-model="material.fieldKey" filterable><el-option v-for="f in definitions.fields" :key="f.key" :value="f.key" :label="`${f.label} (${f.key}) · ${f.type}`"/></el-select></el-form-item><el-form-item label="资料类型"><el-select v-model="material.kind"><el-option v-for="(label,k) in kinds" :key="k" :value="k" :label="label"/></el-select></el-form-item><el-form-item label="字段值（列表、数字、范围用JSON）" class="wide"><el-input v-model="material.valueText" type="textarea" :rows="3" placeholder="例如列表：[&quot;拖动&quot;,&quot;合成&quot;]；工期：{&quot;lower&quot;:8,&quot;upper&quot;:16}"/></el-form-item><el-form-item label="提交人"><el-input v-model="material.submitter"/></el-form-item><el-form-item label="观察日期 / 含时区ISO时间"><el-input v-model="material.observedAt"/></el-form-item><el-form-item label="来源名称"><el-input v-model="material.sourceName"/></el-form-item><el-form-item label="同源家族（转载归同源）"><el-input v-model="material.originFamily"/></el-form-item><el-form-item label="原文 / 片段定位"><el-input v-model="material.locator"/></el-form-item><el-form-item label="来源链接（可空，仅http/https）"><el-input v-model="material.sourceUrl"/></el-form-item><el-form-item label="原文摘录" class="wide"><el-input v-model="material.excerpt" type="textarea" :rows="3"/></el-form-item><el-form-item label="保存权限"><el-select v-model="material.rights"><el-option v-for="s in ['public_excerpt','authorized','internal','not_authorized']" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="目标应用版本（先复核version字段）"><el-input v-model="material.appVersion"/></el-form-item><el-form-item label="资料状态"><el-select v-model="material.status"><el-option v-for="s in ['available','missing','not_supported','not_authorized','not_applicable','stale','conflict']" :key="s" :value="s" :label="labels[s]"/></el-select></el-form-item><el-form-item label="有效期（可空，含时区ISO）"><el-input v-model="material.validUntil"/></el-form-item><el-form-item label="缺失 / 不适用说明"><el-input v-model="material.reason"/></el-form-item><el-form-item label="媒体类型（仅有实际材料时）"><el-select v-model="material.mediaKind" clearable><el-option v-for="s in ['gameplay_screenshot','gameplay_video','ad_video','diagram']" :key="s" :value="s" :label="s"/></el-select></el-form-item><template v-if="material.fieldKey==='mode'"><el-form-item label="广告核查依据"><el-input v-model="material.adBasis"/></el-form-item><el-form-item label="排除内购核查依据"><el-input v-model="material.noIapBasis"/></el-form-item><el-checkbox v-model="material.scopeConfirmed">已确认目标应用版本与市场范围</el-checkbox></template><template v-if="material.kind==='inference'"><el-form-item v-for="k in ['model','promptVersion','schemaVersion','inputHash']" :key="k" :label="k"><el-input v-model="material.modelMetadata[k]"/></el-form-item></template></el-form><template #footer><el-button @click="materialOpen=false">取消</el-button><el-button type="primary" :loading="actionBusy" @click="submitMaterial">提交待复核</el-button></template></el-dialog>
  <el-dialog v-model="reviewOpen" title="材料复核与审计" width="min(650px,94vw)"><p>{{selectedSubmission?.field_key}} · {{selectedSubmission?.material?.sourceName}}</p><pre class="profile-review-text">{{JSON.stringify(selectedSubmission?.material,null,2)}}</pre><el-form label-position="top"><el-form-item label="复核人"><el-input v-model="review.reviewer"/></el-form-item><el-form-item label="决策"><el-select v-model="review.decision"><el-option v-for="s in ['approved','rejected','conflict','needs_material']" :key="s" :value="s" :label="labels[s]"/></el-select></el-form-item><el-form-item label="复核理由（范围、原文、时间、权限和矛盾检查）"><el-input v-model="review.reason" type="textarea"/></el-form-item><el-form-item label="显式裁决替代的旧观察ID（可空）"><el-input v-model="review.supersedesId"/></el-form-item></el-form><template #footer><el-button @click="reviewOpen=false">取消</el-button><el-button type="primary" :loading="actionBusy" @click="saveReview">保存复核</el-button></template></el-dialog>
  <el-dialog v-model="selectionOpen" :title="selection.id?'编辑选用记录':'新增选用记录'" width="min(600px,94vw)"><el-form label-position="top"><el-form-item label="负责人"><el-input v-model="selection.owner" maxlength="40"/></el-form-item><el-form-item label="参考平台实体"><el-select v-model="selection.referenceVersionId"><el-option v-for="v in dossier?.listings||[]" :key="v.id" :value="v.platform_version_id" :label="`${platforms[v.platform]} · ${v.market} (#${v.platform_version_id})`"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="selection.status"><el-option v-for="s in ['SELECTED','IN_PROGRESS','COMPLETED','ABANDONED']" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item v-for="f in [['selectedOn','选用日期'],['startedOn','开始日期'],['finishedOn','完成日期']]" :key="f[0]" :label="f[1]"><el-date-picker v-model="selection[f[0]!]" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="备注"><el-input v-model="selection.note" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="selectionOpen=false">取消</el-button><el-button type="primary" :loading="actionBusy" @click="saveSelection">保存</el-button></template></el-dialog>
</section>
</template>

